#!/bin/bash
# Lädt alle BKZ-Preisblätter in den Ordner PDFs/ neben diesem Skript.
# Aufruf (Linux/macOS/Git-Bash):  bash download.sh
# Schreibt ein eigenes Log download_log_neu.csv und lässt download_log.csv (Stand der Erhebung, mit SHA-256) unverändert.
# Vergleich: Weicht sha256 ab, hat der Netzbetreiber das Dokument seit der Erhebung geändert. Manche Server sperren Skripte (HTTP 403) – dann Fundort in bkz_quellen.csv im Browser öffnen.
cd "$(dirname "$0")" || exit 1
mkdir -p PDFs
LOG="download_log_neu.csv"
echo "id;datei;http_status;bytes;sha256;url" > "$LOG"
UA="BKZ-Datensatz/2026 (Forschungsdaten; Abruf veroeffentlichter Preisblaetter)"
command -v sha256sum >/dev/null && SHA="sha256sum" || SHA="shasum -a 256"
dl() {
  local id="$1" f="$2" url="$3"
  if [ -s "PDFs/$f" ]; then echo "= $f (schon da)"; else
    code=$(curl -sL -A "$UA" --max-time 60 -o "PDFs/$f" -w "%{http_code}" "$url")
    echo "$code  $f"; sleep 1
  fi
  if [ -s "PDFs/$f" ] && head -c 5 "PDFs/$f" | grep -q "%PDF"; then
    sha=$($SHA "PDFs/$f" | cut -d" " -f1); size=$(wc -c < "PDFs/$f" | tr -d " ")
  else
    if [ -s "PDFs/$f" ]; then mv "PDFs/$f" "PDFs/${f%.*}.html"; f="${f%.*}.html"; sha=$($SHA "PDFs/$f" | cut -d" " -f1); size=$(wc -c < "PDFs/$f" | tr -d " "); code="${code:-cached} (HTML, kein PDF)"; else sha="FEHLT"; size=0; fi
  fi
  echo "$id;$f;${code:-cached};$size;$sha;$url" >> "$LOG"
}
